mapper.select:
SELECT /* getComplaintList */
FROM ( SELECT Q.CMPL_NUMB , Q.USER_NUMB , Q.REPORTER_NICK , Q.TAGT_TYPE , Q.TAGT_TYPE_NAME , Q.TAGT_NUMB , Q.TARGET_USER_NICK , Q.CMPL_RSON , Q.CMPL_RSON_NAME , Q.CMPL_CNTN , Q.CMPL_STAT , Q.CMPL_STAT_NAME , Q.PROC_CNTN , Q.PROC_ADMN , Q.PROC_ADMN_NAME , Q.PROC_DATE , Q.REGI_DATE , Q.UPDT_DATE , ROW_NUMBER() OVER ( ORDER BY Q.REGI_DATE DESC , Q.CMPL_NUMB DESC ) AS ROW_NUMB FROM ( SELECT FROM TH_CMPLNT C LEFT JOIN TM_USERXM R ON R.USER_NUMB = C.USER_NUMB LEFT JOIN TM_USERXM T ON T.USER_NUMB = C.TAGT_NUMB AND C.TAGT_TYPE = #{cmplUser} WHERE 1 = 1
) Q ) P WHERE P.ROW_NUMB BETWEEN #{startRow} AND #{endRow} ORDER BY P.ROW_NUMB


   SELECT /* getRelatedComplaintList */

     FROM TH_CMPLNT C
LEFT JOIN TM_USERXM R
       ON R.USER_NUMB = C.USER_NUMB
LEFT JOIN TM_USERXM T
       ON T.USER_NUMB = C.TAGT_NUMB
      AND C.TAGT_TYPE = #{cmplUser}
    WHERE C.TAGT_TYPE = #{tagtType}
      AND C.TAGT_NUMB = #{tagtNumb}
      AND C.CMPL_NUMB != #{cmplNumb}
 ORDER BY C.REGI_DATE DESC
        , C.CMPL_NUMB DESC
    LIMIT 10

SELECT /* getRelatedComplaintCnt */
       COUNT(1)
  FROM TH_CMPLNT C
 WHERE C.TAGT_TYPE = #{tagtType}
   AND C.TAGT_NUMB = #{tagtNumb}
   AND C.CMPL_NUMB != #{cmplNumb}

mapper.update:


UPDATE /* uptComplaint */
       TH_CMPLNT
   SET CMPL_STAT = #{update.cmplStat}
     , PROC_CNTN = #{update.procCntn,jdbcType=VARCHAR}
     , PROC_ADMN = #{procAdmn}
     , PROC_DATE = CASE WHEN #{update.cmplStat} IN (#{cmplActioned}, #{cmplRejected})
                             THEN CURRENT_TIMESTAMP(6)
                        ELSE NULL
                    END
     , UPDT_DATE = CURRENT_TIMESTAMP(6)
 WHERE CMPL_NUMB = #{cmplNumb}
